This is just some example code. We’re not going to run this. I’m going to show you an example from students I had during J-term.


Code
library(shiny)
library(ggplot2)
library(dplyr)
library(palmerpenguins)

ui &lt;- fluidPage(
  selectInput("species", "Species:",
              choices = c("All", unique(na.omit(penguins$species)))),
  plotOutput("plot")
)

server &lt;- function(input, output) {

  filtered &lt;- reactive({
    if (input$species == "All") penguins
    else filter(penguins, species == input$species)
  })

  output$plot &lt;- renderPlot({
    ggplot(filtered(),
           aes(bill_length_mm, flipper_length_mm, color = species)) +
      geom_point() +
      theme_minimal()
  })
}

shinyApp(ui, server)
